<?php

if(!defined('ABSPATH')) {exit;}

// WC_Order::save normally logs and swallows hook exceptions. Confirmed changes must stop instead.
if(class_exists('WC_Order')) {
final class YoRo_Order_Edit_Native_Order extends WC_Order
{
    protected function handle_exception($error,$message='Error') {throw $error;}
}
}

/** Authorizes, quotes and confirms bounded native unpaid-order edits. */
final class YoRo_Order_Edit
{
    public const ReadActions=['orders.get_edit_context'];
    public const WriteActions=['orders.create','orders.update_details'];
    public const ManifestExtension='yoro.early_access_order_edit';
    private const AddressFields=['first_name','last_name','company','address_1','address_2','city','state','postcode','country','email','phone'];
    private const Reasons=['unsupported_order_state','unsupported_integration','bounds_exceeded','invalid_reference','quote_unavailable'];

    private static function invalid(string $reason='invalid_reference'): never {throw new RuntimeException($reason);}
    private static function schema(): array {static $schema;return $schema??=json_decode(self::SchemaJson,true,512,JSON_THROW_ON_ERROR);}
    public static function manifest(): array {return self::schema()['manifest'];}
    public static function properties(string $action): array {return self::schema()['changes_properties'];}
    public static function result_schema(string $action): array {return self::schema()[match($action){'orders.get_edit_context'=>'context_schema','orders.create'=>'create_schema','orders.update_details'=>'update_schema',default=>self::invalid()}];}
    public static function canonical($value) {if(!is_array($value)){return $value;}if(!array_is_list($value)){ksort($value,SORT_STRING);}return array_map([self::class,'canonical'],$value);}
    public static function hash($value): string {return hash('sha256',json_encode(self::canonical($value),JSON_UNESCAPED_UNICODE|JSON_UNESCAPED_SLASHES|JSON_THROW_ON_ERROR));}
    private static function plain($value,int $max,bool $empty=true): bool {return is_string($value)&&strlen($value)<=$max&&($empty||$value!=='')&&trim($value)===$value&&preg_match('//u',$value)===1&&!preg_match('/[\x00-\x1f\x7f<>]/',$value)&&wp_strip_all_tags($value)===$value;}
    private static function amount($value,bool $positive=false): bool {return is_string($value)&&preg_match('/\A(?:0|[1-9][0-9]{0,11})(?:\.[0-9]{1,6})?\z/D',$value)===1&&(!$positive||(float)$value>0);}
    private static function permissions(bool $write,int $id): void {
        if(!current_user_can('manage_woocommerce')||!current_user_can('edit_shop_orders')||!current_user_can('yoro_execute_actions')||!current_user_can($write?'yoro_execute_actions':'yoro_view_store_data')||($id>0&&!current_user_can('edit_shop_order',$id))) {self::invalid();}
    }

    public static function changes($input): array
    {
        if(!is_array($input)||!$input||array_is_list($input)||array_diff(array_keys($input),array_keys(self::properties('orders.create')))) {self::invalid();}
        $changes=$input;
        foreach($changes as$field=>$value) {
            if($field==='customer_id') {if(!is_int($value)||$value<0){self::invalid();}}
            elseif(in_array($field,['billing','shipping'],true)) {$validated=YoRo_Order_Management::changes([$field=>$value],'orders.update_contacts');$changes[$field]=$validated[$field];}
            elseif($field==='recalculate') {if($value!==true){self::invalid();}}
            elseif($field==='coupon_codes') {
                if(!is_array($value)||!array_is_list($value)||count($value)>10){self::invalid('bounds_exceeded');}
                $codes=[];foreach($value as$code){if(!self::plain($code,100,false)){self::invalid();}$code=wc_format_coupon_code($code);if(!self::plain($code,100,false)||in_array($code,$codes,true)){self::invalid();}$codes[]=$code;}$changes[$field]=$codes;
            } elseif(str_starts_with($field,'remove_')) {
                $limit=$field==='remove_line_item_ids'?20:10;if(!is_array($value)||!array_is_list($value)||count($value)>$limit||count(array_unique($value,SORT_REGULAR))!==count($value)){self::invalid();}foreach($value as$id){if(!is_int($id)||$id<1){self::invalid();}}sort($value,SORT_NUMERIC);$changes[$field]=$value;
            } else {
                $line=$field==='line_items';$ship=$field==='shipping_lines';$limit=$line?20:10;
                if(!is_array($value)||!array_is_list($value)||count($value)>$limit){self::invalid('bounds_exceeded');}$seen=[];
                foreach($value as$row){$required=$line?['item_id','product_id','quantity']:($ship?['item_id','method_id','method_title','total']:['item_id','name','total','tax_class','tax_status']);$allowed=[...$required,...($line?['unit_price']:[])];
                    if(!is_array($row)||array_diff($required,array_keys($row))||array_diff(array_keys($row),$allowed)||!is_int($row['item_id'])||$row['item_id']<0||($row['item_id']>0&&in_array($row['item_id'],$seen,true))){self::invalid();}$seen[]=$row['item_id'];
                    if($line){if(!is_int($row['product_id'])||$row['product_id']<1||!is_int($row['quantity'])||$row['quantity']<1||$row['quantity']>1000000||(isset($row['unit_price'])&&!self::amount($row['unit_price']))){self::invalid();}}
                    elseif($ship){if(!self::plain($row['method_id'],100,false)||!self::plain($row['method_title'],200,false)||!self::amount($row['total'])){self::invalid();}}
                    elseif(!self::plain($row['name'],200,false)||!self::amount($row['total'],true)||!self::plain($row['tax_class'],100)||!in_array($row['tax_status'],['taxable','none'],true)){self::invalid();}
                }
            }
        }
        foreach(['line_items','shipping_lines','fee_lines']as$field){foreach($changes[$field]??[]as$i=>$row){foreach(['unit_price','total']as$money){if(isset($row[$money])){$v=rtrim(rtrim($row[$money],'0'),'.');if(!str_contains($row[$money],'.')){$v=$row[$money];}$changes[$field][$i][$money]=$v===''?'0':$v;}}}}
        return self::canonical($changes);
    }

    public static function valid_params(string $action,$params): bool
    {
        if(!is_array($params)||!is_int($params['order_id']??null)||$params['order_id']<0){return false;}
        if($action==='orders.get_edit_context') {try{return !array_diff(array_keys($params),['order_id','changes'])&&(!array_key_exists('changes',$params)||self::changes($params['changes']));}catch(Throwable $e){return false;}}
        try{return in_array($action,self::WriteActions,true)&&($action==='orders.create'?$params['order_id']===0:$params['order_id']>0)&&count($params)===4&&!array_diff(array_keys($params),['order_id','changes','expected_version','expected_quote_hash'])
            &&is_string($params['expected_version']??null)&&preg_match('/\A[a-f0-9]{64}\z/D',$params['expected_version'])===1&&is_string($params['expected_quote_hash']??null)&&preg_match('/\A[a-f0-9]{64}\z/D',$params['expected_quote_hash'])===1&&self::changes($params['changes']);}catch(Throwable $e){return false;}
    }

    private static function address(array $address,string $kind): array
    {
        $fields=$kind==='billing'?self::AddressFields:array_values(array_diff(self::AddressFields,['email']));$result=[];
        foreach($fields as$field){$result[$field]=(string)($address[$field]??'');}
        if(array_diff(array_keys($address),$fields)){self::invalid('unsupported_integration');}
        YoRo_Order_Management::changes([$kind=>$result],'orders.update_contacts');
        $country=$result['country'];$state=$result['state'];$postcode=$result['postcode'];
        if($country!==''&&!isset(WC()->countries->get_countries()[$country])){self::invalid();}
        $states=$country!==''?WC()->countries->get_states($country):[];
        if($state!==''&&($country===''||(is_array($states)&&$states&&!isset($states[$state])))){self::invalid();}
        if($postcode!==''&&$country!==''&&!WC_Validation::is_postcode($postcode,$country)){self::invalid();}
        if($result['phone']!==''&&!WC_Validation::is_phone($result['phone'],$country)){self::invalid();}
        return $result;
    }

    public static function fingerprint(WC_Order $order): array
    {
        $items=[];foreach($order->get_items(['line_item','shipping','fee','coupon','tax'])as$id=>$item){$data=$item->get_data();$items[(string)$id]=$data;}
        return ['order'=>[$order->get_id(),$order->get_status('edit'),$order->get_total('edit'),$order->get_currency('edit'),$order->get_date_modified('edit')?->format(DATE_ATOM),$order->get_address('billing'),$order->get_address('shipping'),$order->get_customer_note('edit')],'customer_id'=>$order->get_customer_id('edit'),'prices_include_tax'=>$order->get_prices_include_tax('edit'),
            'paid'=>$order->get_date_paid('edit')?->getTimestamp(),'transaction_id'=>$order->get_transaction_id('edit'),'refunded'=>$order->get_total_refunded(),'stock_reduced'=>(bool)$order->get_data_store()->get_stock_reduced($order),'recorded_coupon_usage'=>(bool)$order->get_data_store()->get_recorded_coupon_usage_counts($order),'items'=>$items];
    }

    private static function state(?WC_Order $order): array
    {
        $state=['currency'=>$order?$order->get_currency('edit'):get_woocommerce_currency(),'customer_id'=>$order?$order->get_customer_id('edit'):0,
            'billing'=>self::address($order?$order->get_address('billing'):[],'billing'),'shipping'=>self::address($order?$order->get_address('shipping'):[],'shipping'),
            'line_items'=>[],'coupon_codes'=>[],'coupon_usage_credit'=>[],'shipping_lines'=>[],'fee_lines'=>[],'prices_include_tax'=>$order?$order->get_prices_include_tax('edit'):wc_prices_include_tax(),'vat_exempt'=>false];
        if(!$order){return $state;}
        if(!in_array($order->get_status('edit'),['pending','on-hold'],true)||!$order->is_editable()||$order->is_paid()||$order->get_date_paid('edit')||$order->get_transaction_id('edit')!==''||$order->get_total_refunded()!='0'||$order->get_refunds()){self::invalid('unsupported_order_state');}
        if(!in_array($order->get_payment_method('edit'),['','bacs','cheque','cod'],true)){self::invalid('unsupported_integration');}
        foreach(['_tracking_number','_wc_shipment_tracking_items','_aftership_tracking_number','_aftership_tracking_items','_wcast_tracking_number','_wcst_order_trackno','_yith_tracking_code']as$key){if($order->get_meta($key,true,'edit')){self::invalid('unsupported_order_state');}}
        $tracking=YoRo_Order_Management::tracking_fingerprint($order);if(!$tracking['complete']){self::invalid('unsupported_integration');}foreach($tracking['records']??[]as$record){if(($record['is_fulfilled']??false)||($record['status']??'')==='fulfilled'||($record['items']??[])!==[]){self::invalid('unsupported_order_state');}}
        global $wpdb;$counts=$wpdb->get_results($wpdb->prepare("SELECT order_item_type,COUNT(*) AS n FROM {$wpdb->prefix}woocommerce_order_items WHERE order_id=%d GROUP BY order_item_type",$order->get_id()),ARRAY_A);
        if($wpdb->last_error!==''){self::invalid('unsupported_integration');}
        foreach($counts as$count){$max=match($count['order_item_type']){'line_item'=>20,'shipping','fee','coupon'=>10,'tax'=>100,default=>0};if((int)$count['n']>$max){self::invalid('bounds_exceeded');}}
        foreach($order->get_items('line_item')as$id=>$item){$product=$item->get_product();$qty=$item->get_quantity('edit');if(!$product||!is_numeric($qty)||(int)$qty!=$qty||$qty<1||$qty>1000000){self::invalid('unsupported_integration');}$state['line_items'][]=['item_id'=>(int)$id,'product_id'=>$product->get_id(),'quantity'=>(int)$qty,'unit_price'=>YoRo_Order_Edit_Quote::decimal((float)$item->get_subtotal('edit')/$qty)];}
        foreach($order->get_items('shipping')as$id=>$item){if(!in_array($item->get_instance_id('edit'),[0,'0',''],true)){self::invalid('unsupported_integration');}$state['shipping_lines'][]=['item_id'=>(int)$id,'method_id'=>$item->get_method_id('edit'),'method_title'=>$item->get_method_title('edit'),'total'=>YoRo_Order_Edit_Quote::decimal($item->get_total('edit'))];}
        foreach($order->get_items('fee')as$id=>$item){if((float)$item->get_total('edit')<=0){self::invalid('unsupported_integration');}$state['fee_lines'][]=['item_id'=>(int)$id,'name'=>$item->get_name('edit'),'total'=>YoRo_Order_Edit_Quote::decimal($item->get_total('edit')),'tax_class'=>$item->get_tax_class('edit'),'tax_status'=>$item->get_tax_status('edit')];}
        foreach($order->get_items('coupon')as$item){$code=$item->get_code('edit');$state['coupon_codes'][]=$code;
            if($order->get_data_store()->get_recorded_coupon_usage_counts($order)){$coupon=new WC_Coupon($code);$store=$coupon->get_data_store();$identity=$state['customer_id']?:$state['billing']['email'];$usage=$state['customer_id']?$store->get_usage_by_user_id($coupon,$identity):$store->get_usage_by_email($coupon,$identity);$tentative=$store->get_tentative_usages_for_user($coupon->get_id(),[$identity]);
                if($coupon->get_usage_count()<1||$usage-$tentative<1){self::invalid('unsupported_integration');}
                $state['coupon_usage_credit'][$code]=['customer_id'=>$state['customer_id'],'email'=>strtolower($state['billing']['email']),'recorded_identity_usage'=>$usage-$tentative];
            }}
        $state['vat_exempt']=$order->get_meta('is_vat_exempt',true,'edit')==='yes';return $state;
    }

    private static function apply_patch(array $state,array $changes,int $orderId): array
    {
        foreach(['customer_id','billing','shipping','coupon_codes']as$field){if(array_key_exists($field,$changes)){$state[$field]=in_array($field,['billing','shipping'],true)?self::address(array_replace($state[$field],$changes[$field]),$field):$changes[$field];}}
        foreach(['line_items'=>'line_item','shipping_lines'=>'shipping_item','fee_lines'=>'fee_item']as$field=>$stem){$rows=$state[$field];$remove=$changes['remove_'.$stem.'_ids']??[];$seen=[];
            foreach($rows as$index=>$row){if(in_array($row['item_id'],$remove,true)){unset($rows[$index]);$seen[]=$row['item_id'];}}
            if(array_diff($remove,$seen)){self::invalid();}
            foreach($changes[$field]??[]as$row){if($row['item_id']===0){$rows[]=$row;continue;}$found=false;foreach($rows as$index=>$current){if($current['item_id']===$row['item_id']){if($field==='line_items'&&$current['product_id']!==$row['product_id']){self::invalid();}$rows[$index]=$row;$found=true;break;}}if(!$found){self::invalid();}}
            $state[$field]=array_values($rows);if(count($rows)>($field==='line_items'?20:10)){self::invalid('bounds_exceeded');}
        }
        if($orderId===0&&!$state['line_items']){self::invalid();}
        foreach($state['line_items']as&$row){$row['unit_price']=$row['unit_price']??null;}unset($row);
        if($state['customer_id']>0){$user=get_user_by('id',$state['customer_id']);if(!$user){self::invalid();}$customer=new WC_Customer($state['customer_id']);$state['vat_exempt']=$customer->get_is_vat_exempt();}
        foreach($state['shipping_lines']as$row){if(!in_array($row['method_id'],['other','flat_rate','free_shipping'],true)){self::invalid('unsupported_integration');}}
        foreach($state['fee_lines']as$row){if(!in_array($row['tax_class'],array_merge([''],WC_Tax::get_tax_class_slugs()),true)){self::invalid();}}
        return $state;
    }

    private static function facts(?WC_Order $order,array $before,array $after): array
    {
        $products=[];$customers=[];$coupons=[];$stock=[];
        foreach(array_merge($before['line_items'],$after['line_items'])as$row) {
            $id=$row['product_id'];if(isset($products[$id])){continue;}$p=wc_get_product($id);
            if(!$p||!$p->is_type(['simple','variation'])||$p->get_status('edit')!=='publish'||!current_user_can('edit_post',$id)||!$p->is_purchasable()){self::invalid('invalid_reference');}
            if($p->is_type('variation')){$parent=wc_get_product($p->get_parent_id('edit'));if(!$parent||$parent->get_status('edit')!=='publish'||!current_user_can('edit_post',$parent->get_id())){self::invalid();}}
            $products[$id]=$p->get_data();$manager=wc_get_product($p->get_stock_managed_by_id());
            if(!$manager){self::invalid();}$stock[$manager->get_id()]=['data'=>$manager->get_data(),'held'=>wc_get_held_stock_quantity($manager,$order?$order->get_id():0)];
        }
        foreach(array_unique([$before['customer_id'],$after['customer_id']])as$id){if($id>0){$customer=new WC_Customer($id);if(!$customer->get_id()){self::invalid();}$customers[$id]=$customer->get_data();}}
        foreach(array_unique(array_merge($before['coupon_codes'],$after['coupon_codes']))as$code){$coupon=new WC_Coupon($code);if(!$coupon->get_id()){self::invalid();}$store=$coupon->get_data_store();$identities=[];foreach([$before,$after]as$state){$identity=$state['customer_id']?:$state['billing']['email'];$identities[(string)$identity]=['usage'=>$state['customer_id']?$store->get_usage_by_user_id($coupon,$identity):$store->get_usage_by_email($coupon,$identity),'tentative'=>$store->get_tentative_usages_for_user($coupon->get_id(),[$identity])];}$coupons[$code]=['data'=>$coupon->get_data(),'usage_count'=>$coupon->get_usage_count(),'tentative'=>$store->get_tentative_usage_count($coupon->get_id()),'identities'=>$identities];}
        $options=[];foreach(['woocommerce_currency','woocommerce_price_num_decimals','woocommerce_prices_include_tax','woocommerce_calc_taxes','woocommerce_tax_round_at_subtotal','woocommerce_tax_based_on','woocommerce_shipping_tax_class','woocommerce_default_country','woocommerce_store_address','woocommerce_store_address_2','woocommerce_store_city','woocommerce_store_postcode','woocommerce_manage_stock','woocommerce_hold_stock_minutes','woocommerce_tax_classes','timezone_string','gmt_offset']as$key){$options[$key]=get_option($key);}
        global $wpdb;$rates=$wpdb->get_results("SELECT * FROM {$wpdb->prefix}woocommerce_tax_rates ORDER BY tax_rate_id LIMIT 1001",ARRAY_A);if($wpdb->last_error!==''||count($rates)>1000){self::invalid('bounds_exceeded');}
        $locations=$wpdb->get_results("SELECT * FROM {$wpdb->prefix}woocommerce_tax_rate_locations ORDER BY location_id LIMIT 5001",ARRAY_A);if($wpdb->last_error!==''||count($locations)>5000){self::invalid('bounds_exceeded');}
        return ['order'=>$order?self::fingerprint($order):null,'actor'=>get_current_user_id(),'caps'=>[current_user_can('manage_woocommerce'),current_user_can('edit_shop_orders'),current_user_can('yoro_execute_actions')],
            'products'=>$products,'customers'=>$customers,'coupons'=>$coupons,'stock'=>$stock,'options'=>$options,'rates'=>$rates,'locations'=>$locations];
    }

    private static function stock_effects(?WC_Order $order,array $before,array $after,array $facts): array
    {
        $reduced=$order&&(bool)$order->get_data_store()->get_stock_reduced($order);$old=[];$wanted=[];
        if($order){foreach($order->get_items('line_item')as$id=>$item){$n=$item->get_meta('_reduced_stock',true,'edit');if($n===''){$n=0;}if(!is_numeric($n)||(int)$n!=$n||$n<0||$n>1000000||(!$reduced&&$n!=0)||$item->get_meta('_restock_refunded_items',true,'edit')){self::invalid('unsupported_integration');}$old[(int)$id]=(int)$n;}}
        $delta=[];$demand=[];
        foreach($before['line_items']as$row){$p=wc_get_product($row['product_id']);if($p->managing_stock()){$manager=$p->get_stock_managed_by_id();$delta[$manager]=($delta[$manager]??0)+($old[$row['item_id']]??0);}}
        foreach($after['line_items']as$row){$p=wc_get_product($row['product_id']);if($p->managing_stock()){$manager=$p->get_stock_managed_by_id();$demand[$manager]=($demand[$manager]??0)+$row['quantity'];$delta[$manager]=($delta[$manager]??0)-($reduced?$row['quantity']:0);}$wanted[$row['item_id']]=$row['quantity'];}
        $effects=[];foreach(array_unique(array_merge(array_keys($delta),array_keys($demand)))as$id){$p=wc_get_product($id);$qty=$p->get_stock_quantity('edit');if(!is_numeric($qty)||(int)$qty!=$qty||abs((int)$qty)>1000000000){self::invalid('unsupported_integration');}$qty=(int)$qty;$change=$delta[$id]??0;$held=$facts['stock'][$id]['held']??0;
            if(!$p->backorders_allowed()&&($reduced?$qty+$change-$held<0:($demand[$id]??0)>$qty-$held)){self::invalid('quote_unavailable');}
            if($change!==0){if(abs($qty+$change)>1000000000||abs($change)>1000000000){self::invalid('bounds_exceeded');}$effects[]=['product_id'=>(int)$id,'quantity_before'=>$qty,'quantity_after'=>$qty+$change,'delta'=>$change];}}
        usort($effects,static fn($a,$b)=>$a['product_id']<=>$b['product_id']);return $effects;
    }

    private static function build(int $id,?array $changes,bool $write=false): array
    {
        self::permissions($write,$id);$order=$id?wc_get_order($id):null;if($id&&(!$order instanceof WC_Order||$order->get_type()!=='shop_order')){self::invalid();}
        $before=self::state($order);$after=$changes===null?$before:self::apply_patch($before,$changes,$id);$facts=self::facts($order,$before,$after);
        $quote=null;$native=null;if($changes!==null){$effects=self::stock_effects($order,$before,$after,$facts);try{$native=YoRo_Order_Edit_Quote::calculate($after);}catch(Throwable $e){self::invalid('quote_unavailable');}$quote=$native['quote'];if(count($quote['tax_lines'])>100){self::invalid('bounds_exceeded');}$quote['stock_effects']=$effects;}
        $quoteHash=$quote!==null?self::hash($quote):null;$version=self::hash(['facts'=>$facts,'changes'=>$changes,'quote_hash'=>$quoteHash]);
        $fields=array_intersect_key($before,array_flip(['customer_id','billing','shipping','line_items','coupon_codes','shipping_lines','fee_lines']));
        $data=['target'=>['id'=>$id,'version'=>$version],'editable'=>true,'quoted'=>$changes!==null,'reason'=>null,'fields'=>$fields,'normalized_changes'=>$changes??(object)[],
            'quote'=>$quote,'quote_hash'=>$quoteHash,'currency'=>$before['currency'],'decimal_places'=>wc_get_price_decimals()];
        if(strlen(wp_json_encode($data))>49152){self::invalid('bounds_exceeded');}
        return ['data'=>$data,'order'=>$order,'before'=>$before,'state'=>$after,'native'=>$native,'facts'=>$facts];
    }

    public static function read_context($params): array|WP_Error
    {
        try{$params=array_diff_key((array)$params,array_flip(['_yoro_confirmed','_yoro_preview']));if(!self::valid_params('orders.get_edit_context',$params)){self::invalid();}
            $built=self::build($params['order_id'],isset($params['changes'])?self::changes($params['changes']):null);return self::result('orders.get_edit_context',$built['data'],true);
        }catch(Throwable $error){return new WP_Error('order_edit_context_unavailable','The bounded order quotation is unavailable: '.(in_array($error->getMessage(),self::Reasons,true)?$error->getMessage():'unsupported_integration').'.');}
    }

    public static function execute_read(array $operation): array|WP_Error
    {
        if(($operation['action']??null)!=='orders.get_edit_context'||!self::valid_params('orders.get_edit_context',$operation['params']??null)){return new WP_Error('order_edit_context_invalid','The quotation selector is invalid.');}
        return self::read_context($operation['params']);
    }

    public static function prepare(array $params,string $action): array|WP_Error
    {
        try{$params=array_diff_key($params,array_flip(['_yoro_confirmed','_yoro_preview']));if(!self::valid_params($action,$params)){self::invalid();}$changes=self::changes($params['changes']);$built=self::build($params['order_id'],$changes,true);
            if(!hash_equals($built['data']['target']['version'],$params['expected_version'])||!hash_equals($built['data']['quote_hash'],$params['expected_quote_hash'])){return new WP_Error('order_edit_version_conflict','The order, product, customer, coupon, stock or tax facts changed. Request a fresh quotation.');}
            return $built;
        }catch(Throwable $error){return new WP_Error('order_edit_unavailable','The quoted native order change is unavailable: '.(in_array($error->getMessage(),self::Reasons,true)?$error->getMessage():'unsupported_integration').'.');}
    }

    public static function preview(array $params,string $action): array|WP_Error
    {
        $built=self::prepare($params,$action);if(is_wp_error($built)){return $built;}$data=$built['data'];
        return ['success'=>true,'read_only'=>true,'undoable'=>false,'order_id'=>$params['order_id'],'before'=>$data['fields'],'after'=>$data['normalized_changes'],'quote'=>$data['quote'],'quote_hash'=>$data['quote_hash'],'stock_effects'=>$data['quote']['stock_effects'],
            'effects'=>['Create remains unpaid and pending; no charge, refund or invoice email is requested.','Existing reduced inventory is adjusted only by the reviewed per-product deltas. Native save and stock hooks may run after confirmation.'],
