    private static function persist(array $built): WC_Order
    {
        $state=$built['state'];$order=new YoRo_Order_Edit_Native_Order($built['order']?$built['order']->get_id():0);$wasReduced=$order->get_id()&&(bool)$order->get_data_store()->get_stock_reduced($order);
        if($wasReduced&&!function_exists('wc_maybe_adjust_line_item_product_stock')){require_once WC_ABSPATH.'includes/admin/wc-admin-functions.php';}
        if($order->get_id()&&$order->get_data_store()->get_recorded_coupon_usage_counts($order)){
            $usedBy=$order->get_customer_id('edit')?:$order->get_billing_email('edit');foreach($order->get_items('coupon')as$item){$coupon=new WC_Coupon($item->get_code('edit'));$coupon->decrease_usage_count($usedBy);}
            $order->get_data_store()->set_recorded_coupon_usage_counts($order,false);
        }
        $order->set_customer_id($state['customer_id']);$order->set_currency($state['currency']);$order->set_address($state['billing'],'billing');$order->set_address($state['shipping'],'shipping');$order->set_prices_include_tax($state['prices_include_tax']);
        if(!$order->get_id()){$order->set_status('pending');$order->set_created_via('yoro');}
        $order->update_meta_data('is_vat_exempt',$state['vat_exempt']?'yes':'no');$order->save();
        $keep=array_column($state['line_items'],'item_id');
        foreach($order->get_items('line_item')as$id=>$item){if(!in_array((int)$id,$keep,true)){if($wasReduced){$adjusted=wc_maybe_adjust_line_item_product_stock($item,0);if(is_wp_error($adjusted)){throw new RuntimeException('Stock restore failed.');}}$order->remove_item($id);}}
        foreach(['shipping'=>'shipping_lines','fee'=>'fee_lines']as$type=>$field){$keep=array_column($state[$field],'item_id');foreach($order->get_items($type)as$id=>$item){if(!in_array((int)$id,$keep,true)){$order->remove_item($id);}}}
        foreach($order->get_items(['coupon','tax'])as$id=>$item){$order->remove_item($id);}
        $mapped=['line_items'=>[],'shipping_items'=>[],'fee_items'=>[]];
        foreach(['line_items'=>'line_item','shipping_items'=>'shipping','fee_items'=>'fee']as$key=>$type){foreach($built['native'][$key]as$entry){$quoted=$entry['item'];$item=$entry['reference_id']?$order->get_item($entry['reference_id']):$quoted;
            if(!$item||$item->get_type()!==$type){throw new RuntimeException('The reviewed item disappeared.');}
            if($type==='line_item'){$item->set_quantity($quoted->get_quantity('edit'));$item->set_subtotal($quoted->get_subtotal('edit'));$item->set_total($quoted->get_total('edit'));$item->set_taxes($quoted->get_taxes('edit'));}
            elseif($type==='shipping'){$item->set_method_id($quoted->get_method_id('edit'));$item->set_instance_id(0);$item->set_method_title($quoted->get_method_title('edit'));$item->set_total($quoted->get_total('edit'));$item->set_taxes($quoted->get_taxes('edit'));}
            else{$item->set_name($quoted->get_name('edit'));$item->set_amount($quoted->get_amount('edit'));$item->set_total($quoted->get_total('edit'));$item->set_tax_class($quoted->get_tax_class('edit'));$item->set_tax_status($quoted->get_tax_status('edit'));$item->set_taxes($quoted->get_taxes('edit'));}
            $item->set_order_id($order->get_id());$order->add_item($item);$item->save();
            if($type==='line_item'&&$wasReduced){$adjusted=wc_maybe_adjust_line_item_product_stock($item,$item->get_quantity('edit'));if(is_wp_error($adjusted)){throw new RuntimeException('Stock adjustment failed.');}}
            $mapped[$key][]=$item->get_id();
        }}
        foreach($built['data']['quote']['coupon_lines']as$row){$item=new WC_Order_Item_Coupon();$item->set_code($row['code']);$item->set_discount($row['discount']);$item->set_discount_tax($row['discount_tax']);$item->add_meta_data('coupon_info',$built['native']['coupons'][$row['code']]->get_short_info(),true);$order->add_item($item);}
        $order->calculate_totals(true);wc_update_coupon_usage_counts($order->get_id());$fresh=wc_get_order($order->get_id());
        if(!$fresh instanceof WC_Order){throw new RuntimeException('The saved order could not be read.');}
        self::verify_saved($fresh,$built,$mapped);
        return $fresh;
    }

    private static function verify_saved(WC_Order $order,array $built,array $mapped): void
    {
        $quote=$built['data']['quote'];$dp=$quote['decimal_places'];$state=$built['state'];
        if($order->get_currency('edit')!==$state['currency']||$order->get_customer_id('edit')!==$state['customer_id']||$order->get_address('billing')!==$state['billing']||$order->get_address('shipping')!==$state['shipping']||$order->get_prices_include_tax('edit')!==$state['prices_include_tax']||$order->get_status('edit')!==($built['order']?$built['order']->get_status('edit'):'pending')||$order->is_paid()||$order->get_date_paid('edit')){throw new RuntimeException('Saved order identity changed.');}
        $actual=['subtotal'=>$order->get_subtotal(),'discount_total'=>$order->get_discount_total('edit'),'discount_tax'=>$order->get_discount_tax('edit'),'shipping_total'=>$order->get_shipping_total('edit'),'shipping_tax'=>$order->get_shipping_tax('edit'),'fee_total'=>$order->get_total_fees(),'cart_tax'=>$order->get_cart_tax('edit'),'total'=>$order->get_total('edit')];
        foreach($actual as$field=>$value){if(YoRo_Order_Edit_Quote::decimal($value,$dp)!==$quote['totals'][$field]){throw new RuntimeException('Saved totals differ from the reviewed quote: '.$field);}}
        foreach($quote['line_items']as$i=>$row){$item=$order->get_item($mapped['line_items'][$i]);$product=$item->get_product();if(!$product||$product->get_id()!==$row['product_id']||(int)$item->get_quantity('edit')!==$row['quantity']){throw new RuntimeException('Saved line identity changed.');}foreach(['subtotal','subtotal_tax','total','total_tax']as$field){$getter='get_'.$field;if(YoRo_Order_Edit_Quote::decimal($item->$getter('edit'))!==$row[$field]){throw new RuntimeException('Saved line values changed.');}}}
        foreach(['shipping_lines'=>'shipping_items','fee_lines'=>'fee_items']as$key=>$mappedKey){foreach($quote[$key]as$i=>$row){$item=$order->get_item($mapped[$mappedKey][$i]);foreach(['total','total_tax']as$field){$getter='get_'.$field;if(YoRo_Order_Edit_Quote::decimal($item->$getter('edit'))!==$row[$field]){throw new RuntimeException('Saved charge values changed.');}}if($key==='shipping_lines'&&($item->get_method_id('edit')!==$row['method_id']||$item->get_method_title('edit')!==$row['method_title'])){throw new RuntimeException('Saved shipping changed.');}if($key==='fee_lines'&&($item->get_name('edit')!==$row['name']||$item->get_tax_class('edit')!==$row['tax_class']||$item->get_tax_status('edit')!==$row['tax_status'])){throw new RuntimeException('Saved fee changed.');}}}
        $coupons=[];foreach($order->get_items('coupon')as$item){$coupons[]=['code'=>$item->get_code('edit'),'discount'=>YoRo_Order_Edit_Quote::decimal($item->get_discount('edit')),'discount_tax'=>YoRo_Order_Edit_Quote::decimal($item->get_discount_tax('edit'))];}
        if($coupons!==$quote['coupon_lines']){throw new RuntimeException('Saved coupons changed.');}
        foreach($quote['stock_effects']as$effect){$product=wc_get_product($effect['product_id']);if(!$product||(int)$product->get_stock_quantity('edit')!==$effect['quantity_after']){throw new RuntimeException('Saved inventory differs from its reviewed delta.');}}
    }

    public static function write(array $params,string $action): array|WP_Error
    {
        if(($params['_yoro_confirmed']??null)!==true||($params['_yoro_preview']??false)!==false){return new WP_Error('order_edit_confirmation_required','Use the confirmed native order executor.');}
        $built=self::prepare($params,$action);if(is_wp_error($built)){return $built;}
        try{$order=self::persist($built);$data=['order_id'=>$order->get_id(),...($action==='orders.create'?['source_order_id'=>0]:[]),'changes'=>$built['data']['normalized_changes'],'quote'=>$built['data']['quote'],'quote_hash'=>$built['data']['quote_hash'],'current_version'=>self::hash(self::fingerprint($order))];return self::result($action,$data,false);}
        catch(Throwable $error){return new WP_Error('local_execution_outcome_unknown','Read the order and inventory again; do not repeat this native change.');}
    }

    private static function result(string $action,array $data,bool $read): array
    {
        $message=$read?'Native unpaid order editing context and optional exact quotation loaded.':'Confirmed native unpaid order change completed. No charge, refund or invoice email was requested.';
        return ['success'=>true,'action'=>$action,'message'=>$message,'summary'=>$message,'data'=>$data,'read_only'=>$read,'undoable'=>false,'result_type'=>'order_edit','display_type'=>'order_edit','assistant_summary'=>$message,'extensions'=>(object)[]];
    }

    public static function input_properties(string $action): array
    {
        $order=['type'=>'integer','minimum'=>0,...($action==='orders.create'?['maximum'=>0]:($action==='orders.update_details'?['minimum'=>1]:[]))];$changes=['type'=>'object','properties'=>self::properties($action),'required'=>[],'additionalProperties'=>false];
        return $action==='orders.get_edit_context'?['order_id'=>$order,'changes'=>$changes]:['order_id'=>$order,'changes'=>$changes,'expected_version'=>['type'=>'string','pattern'=>'^[a-f0-9]{64}$'],'expected_quote_hash'=>['type'=>'string','pattern'=>'^[a-f0-9]{64}$']];
    }

    public static function register(): void
