            YoRo_Action_Registry::register($action,['label'=>match($action){'orders.create'=>'Create unpaid pending order','orders.update_details'=>'Edit unpaid order',default=>'Read order editing context and quotation'},'description'=>'Bounded native unpaid order line items, customer, coupons, shipping, positive fees, tax and inventory deltas. Preview never persists an order.','category'=>'orders','permission'=>$write?'yoro_execute_actions':'yoro_view_store_data',
                'callback'=>$write?static fn($params)=>self::write((array)$params,$action):[self::class,'read_context'],'preview_callback'=>$write?static fn($params)=>self::preview((array)$params,$action):[self::class,'read_context'],
                'risk_level'=>$write?'medium':'low','write_action'=>$write,'requires_confirmation'=>$write,'effect'=>$write?'mutate':'read','reversibility'=>'none','target_type'=>'order','max_items'=>1,'input_schema'=>$input,'canonical_input_schema'=>$properties,'required_params'=>$write?array_keys($properties):['order_id'],'concurrency_strategy'=>$write?'optimistic_version':'','capabilities'=>['orders',$write?'write':'read']]);
        }
    }

